gMS(){return"\u0627\u0644\u0639\u0646\u0648\u0627\u0646"},
gOt(){return"\u0627\u0644\u0647\u0627\u062a\u0641"},
gNd(){return"\u0647\u0648\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629"},
