gNb(){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06d5\u06a9\u0627\u0646\u06cc \u0644\u0642"},
gOq(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06cc \u0626\u06c6\u0646\u0644\u0627\u06cc\u0646"},
gOr(){return"\u0695\u06ce\u06af\u06d5 \u0628\u062f\u06d5 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u0627\u0646 \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5 \u0695\u06ce\u06af\u06d5\u06cc \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06ce\u06a9\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u0648\u06d5 \u067e\u0627\u0631\u06d5\u062a \u0628\u062f\u06d5\u0646\u06ce. \u0647\u06d5\u0631 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06ce\u06a9 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0628\u0627\u0632\u0631\u06af\u0627\u0646\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a\u06cc \u062e\u06c6\u06cc \u067e\u06ce\u0648\u06cc\u0633\u062a\u06d5\u060c \u0628\u06d5 \u062c\u06cc\u0627 \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u06d5\u0648 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5 \u0695\u06ce\u06a9\u062f\u06d5\u062e\u0631\u06ce\u062a."},
gNP(){return"\u0686\u0627\u0644\u0627\u06a9\u06d5"},
gNS(){return"\u0695\u06ce\u06a9\u0646\u06d5\u062e\u0631\u0627\u0648\u06d5"},
gNL(){return"\u0628\u06d5\u0645 \u0632\u0648\u0648\u0627\u0646\u06d5"},
gNM(){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646"},
NO(a){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06cc "+a},
gNQ(){return"\u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0644\u06d5 \u0695\u06ce\u06af\u06d5\u06cc \u0626\u06d5\u0645 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5\u0648\u06d5"},
gNN(){return"\u0628\u06c6 \u0647\u06ce\u0634\u062a\u0646\u06d5\u0648\u06d5\u06cc \u0646\u0631\u062e\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648 \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5\u0648\u06d5"},
gNU(){return"\u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5."},
NT(a){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u062f\u0646 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
gNR(){return"\u0647\u06d5\u0631 \u0633\u06ce \u062e\u0627\u0646\u06d5\u06a9\u06d5 \u067e\u0695\u0628\u06a9\u06d5\u0648\u06d5\u060c \u06cc\u0627\u0646 \u0647\u06d5\u0631 \u0633\u06ce\u06cc\u0627\u0646 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0648\u06d5 \u0628\u06c6 \u0647\u06ce\u0634\u062a\u0646\u06d5\u0648\u06d5\u06cc \u0646\u0631\u062e\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648."},
gPp(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u062c\u0632\u062f\u0627\u0646 (msisdn)"},
